#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float3 amzp_pos;
uniform float amzp_density;
uniform float amzp_evolution;
uniform float amzp_seed;
uniform float amzp_scale;
uniform float amzp_shapeSize;
uniform float amzp_shapeAngle;
uniform float amzp_sizeVariance;
uniform float amzp_angleVariance;
uniform float amzp_layerCount;
uniform float amzp_fade;
uniform float amzp_alpha;
uniform float amzp_slack;
uniform float amzp_blendMode;
uniform float amzp_coloring;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_color3;
uniform float amzp_lockLuminance;
uniform float amzp_lockSaturation;
uniform float amzp_interpHue;
        float rand2(float2 co){
            return fract(sin(dot(co.xy ,float2(12.9898,78.233))) * 43758.5453);
        }
        float rand3 (float3 v) {
            return fract(sin(dot(v,float3(12.9898,78.233,193.71)))*43758.5453123);
        }
        float rand4 (float4 v) {
            return fract(sin(dot(v,float4(12.9898,78.233,193.71,397.318)))*43758.5453123);
        }
        float2 randVec2(float3 v) {
            return float2( rand4(float4(v,5.124)), rand4(float4(v,3.0)));
        }
        float3 randVec3(float3 v) {
            return float3( rand4(float4(v,5.124)), rand4(float4(v,7.23464)), rand4(float4(v,3.0)));
        }
        float2 l2s( float2 v ) {
            return (float4(v,0.,1.)*amzLayerToScreen()).xy;
        }
        float2x2 rot(float a) {
            float c = cos(a);
            float s = sin(a);
            return float2x2(
                c, -s,
                s, c
            );
        }
        float3 hsv2rgb(float3 c)
        {
            float4 K = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
            float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
            return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
        }
        float3 rgb2hsv(float3 c)
        {
            float4 K = float4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
            float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
            float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
            float d = q.x - min(q.w, q.y);
            float e = 1.0e-10;
            return float3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
        }
        float4 mixColors(float4 a, float4 b, float t) {
            float4 result;
            if( (amzp_interpHue>0.5) ) {
                result = float4(hsv2rgb(mix(rgb2hsv(a.rgb),rgb2hsv(b.rgb),t)),mix(a.a,b.a,t));
            } else {
                result = mix(a,b,t);
            }
            return result;
        }
        float4 getColor(float3 id, float layerDepth) {
            float4 result;
            if( int(amzp_coloring)==0 ) {
                result = float4(0.);
            } else if( int(amzp_coloring)==1 ) {
                result = amzp_color1;
            } else if( int(amzp_coloring)==2 ) {
                result = amzp_color1 * rand4(float4(id,0.1974));
            } else if( int(amzp_coloring)==3 ) {
                result = mixColors(amzp_color1,amzp_color2,rand4(float4(id,0.1974)));
            } else if( int(amzp_coloring)==4 ) {
                float2 rr = randVec2(id);
                result = mixColors(mixColors(amzp_color1,amzp_color2,rr.x),amzp_color3,rr.y);
            } else if( int(amzp_coloring)==5 ) {
                result = amzp_color1 * layerDepth;
            } else if( int(amzp_coloring)==6 ) {
                result = mixColors(amzp_color1,amzp_color2,layerDepth);
            } else if( int(amzp_coloring)==7 ) {
                result = layerDepth < 0.5 ? mixColors(amzp_color1,amzp_color2,layerDepth*2.) : mixColors(amzp_color2,amzp_color3,(layerDepth-0.5)*2.);
            } else if( int(amzp_coloring)==8 ) {
                result = mixColors(amzp_color3,mixColors(amzp_color1,amzp_color2,rand4(float4(id,0.1974))),layerDepth);
            } else {
                result = float4(0.);
            }
            return result;
        }
        float4 shapeGrid(float2 st, float amzLocal_layer, float layerDepth) {
            st *= 10.;
            float2 uv = fract(st);
            float3 id = float3(floor(st),amzLocal_layer);
            float amzLocal_size = amzp_sizeVariance < 0.0001 ? amzp_shapeSize : min(amzp_shapeSize, amzp_shapeSize * (1.+((rand4(float4(id,0.351))-0.5)*amzp_sizeVariance)));
            float angle = amzp_angleVariance < 0.0001 ? 0. : ((rand4(float4(id,0.2793))-0.5)*amzp_angleVariance*12.56636);
            float rr = rand3(id);
            amzLocal_size *= smoothstep(rr,rr+0.008,amzp_density);
            if( amzLocal_size < 0.00001 ) return float4(0.);
            uv -= 0.5;
            uv *= layer.x > layer.y ? float2(1.,layer.x/layer.y) : float2(layer.y/layer.x,1.);
            uv /= amzLocal_size;
            float maxDisplace = (1./amzLocal_size - 1.);
            float2 displace;
            if( abs(amzp_evolution) > 0.001 ) {
                displace = mix(randVec2(id+floor(amzp_evolution)),randVec2(id+floor(amzp_evolution+1.)),fract(amzp_evolution));
            } else {
                displace = randVec2(id);
            }
            uv += clamp((displace-0.5)*max(1.0,maxDisplace)*amzp_slack,-maxDisplace,maxDisplace);
            uv *= rot(angle + (amzp_shapeAngle * 0.0174532925));
            uv += 0.5;
            uv.y = 1. - uv.y;
            float4 texColor = amzTexture(0,l2s(uv));
            float4 blendColor = getColor(id,layerDepth);
            float4 result;
            if((amzp_lockLuminance>0.5) || (amzp_lockSaturation>0.5)) {
                float3 texHsv = rgb2hsv(texColor.a <= 0.0 ? float3(0.) : (texColor.rgb/texColor.a));
                float3 blendHsv = rgb2hsv(blendColor.a <= 0.0 ? float3(0.) : (blendColor.rgb/blendColor.a));
                if( (amzp_lockLuminance>0.5) ) blendHsv.z = texHsv.z;
                if( (amzp_lockSaturation>0.5) ) blendHsv.y = texHsv.y;
                result = float4(hsv2rgb(mix(texHsv, blendHsv, blendColor.a)),1.) * texColor.a;
            } else {
                result = float4(mix(texColor.a <= 0.0 ? float3(0.) : (texColor.rgb/texColor.a), blendColor.a <= 0.0 ? float3(0.) : (blendColor.rgb/blendColor.a), blendColor.a),1.) * texColor.a;
            }
            return result;
        }
        void amzRender() {
            float2 st = amzLayerNorm();
            st.y = 1. - st.y;
            st -= 0.5;
            st.x *= layer.x/layer.y;
            st /= amzp_scale*6.;
            float2 parallax = (amzp_pos.xy / 1000.) + 25.35;
            float depth = amzp_pos.z / 100.;
            float4 result = float4(0.);
            float f = fract(depth);
            float amzLocal_layer = floor(depth);
            float filteredSeed = amzp_seed/5.0;
            for( float i=amzp_layerCount-1.; i>=0.; i -= 1. ) {
                float2 uv = st;
                uv *= ((1.+i)-f)/9.;
                uv += parallax;
                float layerDepth = smoothstep(amzp_layerCount,amzp_layerCount*(0.9999-amzp_fade),(i+1.)-f);
                float4 color = shapeGrid(uv, amzLocal_layer+i+filteredSeed, layerDepth)*amzp_alpha*layerDepth;
                if( int(amzp_blendMode)==1 ) {
                    float3 fg = color.a<0.0001 ? float3(0.) : color.rgb/color.a;
                    float3 bg = result.a<0.0001 ? float3(1.) : result.rgb/result.a;
                    result = result * (1.-color.a) + float4(fg*bg,1.0)*color.a;
                } else if( int(amzp_blendMode)==2 ) {
                    float3 fg = color.a<0.0001 ? float3(1.) : color.rgb/color.a;
                    float3 bg = result.a<0.0001 ? float3(0.) : result.rgb/result.a;
                    result = result * (1.-color.a) + float4(1.-(1.-fg)*(1.-bg),1.0)*color.a;
                } else {
                    result = result * (1.-color.a) + color;
                }
            }
            amzOutput = result;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
